local _, addon = ...
addon.Options.Window = addon.Options.Window or {}
local window = addon.Options.Window
window.Help = window.Help or {}
local help = window.Help

-- The explanation the options window's help pane draws per section (docs/work/2026-10-25-options-revamp/plan-help.md),
-- read through the seam Help[sectionId] = {Title, Blocks, ShowMe, ShowMeSecure, ShowMeNote}; ShowMe.lua adds the last
-- three. Each line is its own string, and a term reuses the label the player already sees in the game. A picture's size
-- comes from Pictures.lua, generated by .claude/tools/Make-HelpPictures.ps1; one not made yet is left out and listed in
-- HelpMissingPictures for the help suite.

local L = addon.L
local isMainline = addon.Util.IsMainline
local media = "Interface/AddOns/Krowi_AchievementFilter/Media/Help/"

window.HelpMissingPictures = {}

local function Picture(name)
    local size = window.HelpPictures and window.HelpPictures[name]
    if not size then
        tinsert(window.HelpMissingPictures, name)
        return
    end
    return {Picture = media .. name, Width = size.Width, Height = size.Height, TexCoords = size.TexCoords}
end

local function Heading(text)
    return {Heading = text}
end

local function Text(text)
    return {Text = text}
end

local function Term(term, text)
    return {Term = term, Text = text}
end

local function Atlas(name)
    return "|A:" .. name .. ":16:16|a"
end

-- Drops the nils, so a picture not made yet or a line of the other client leaves no hole
local function Blocks(...)
    local blocks = {}
    for i = 1, select("#", ...) do
        local block = select(i, ...)
        if block then
            tinsert(blocks, block)
        end
    end
    return blocks
end

local function RetailOnly(block)
    return isMainline and block or nil
end

